package com.bank.dlt;

import java.util.function.Predicate;
import java.util.logging.Logger;

// A declarative data-quality rule: @dlt.expect / expect_or_drop / expect_or_fail.
class Expectation {
    private static final Logger log = Logger.getLogger(Expectation.class.getName());

    enum Action { KEEP, DROP, FAIL }

    final String name;
    final Predicate<Row> rule;
    final Action action;

    Expectation(String name, Predicate<Row> rule, Action action) {
        this.name = name;
        this.rule = rule;
        this.action = action;
    }

    // Returns true if the row should be KEPT in the output; throws if FAIL action violated.
    boolean evaluate(Row row, int[] passFailCounts) {
        boolean ok = rule.test(row);
        if (ok) { passFailCounts[0]++; return true; }
        passFailCounts[1]++;
        switch (action) {
            case KEEP -> { log.warning(() -> "Expectation '" + name + "' violated by " + row + " (kept, recorded)"); return true; }
            case DROP -> { log.warning(() -> "Expectation '" + name + "' violated by " + row + " (DROPPED)"); return false; }
            case FAIL -> throw new IllegalStateException("Expectation '" + name + "' violated by " + row + " → pipeline FAILS");
        }
        return true;
    }
}
