package com.bank.dlt;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

// A declared DLT table: its name, upstream dependencies, a transform, and expectations.
class DltTable {
    final String name;
    final List<String> dependsOn;                 // DLT auto-derives order from these
    final Function<List<Row>, List<Row>> transform; // how rows are produced from input
    final List<Expectation> expectations = new ArrayList<>();
    final List<Row> output = new ArrayList<>();

    DltTable(String name, List<String> dependsOn, Function<List<Row>, List<Row>> transform) {
        this.name = name;
        this.dependsOn = dependsOn;
        this.transform = transform;
    }

    DltTable expect(Expectation e) { expectations.add(e); return this; }
}
