package com.bank.dlt;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.logging.Logger;

// The declarative framework: register tables, auto-order by dependencies, run with quality.
class DltPipeline {
    private static final Logger log = Logger.getLogger(DltPipeline.class.getName());

    private final Map<String, DltTable> tables = new LinkedHashMap<>();
    private final Map<String, List<Row>> sources = new HashMap<>();

    void addSource(String name, List<Row> rows) { sources.put(name, rows); }
    DltTable table(DltTable t) { tables.put(t.name, t); return t; }

    // Topologically order tables by their declared dependencies — NO manual sequencing.
    private List<DltTable> resolveOrder() {
        List<DltTable> ordered = new ArrayList<>();
        Set<String> done = new HashSet<>(sources.keySet());
        while (ordered.size() < tables.size()) {
            boolean progressed = false;
            for (DltTable t : tables.values()) {
                if (done.contains(t.name)) continue;
                if (done.containsAll(t.dependsOn)) {
                    ordered.add(t);
                    done.add(t.name);
                    progressed = true;
                    log.info(() -> "Resolved '" + t.name + "' (depends on " + t.dependsOn + ")");
                }
            }
            if (!progressed) throw new IllegalStateException("Cyclic or missing dependency");
        }
        return ordered;
    }

    void run() {
        log.info("DLT pipeline starting — framework resolves dependency order automatically");
        for (DltTable t : resolveOrder()) {
            List<Row> input = new ArrayList<>();
            for (String dep : t.dependsOn) {
                input.addAll(sources.containsKey(dep) ? sources.get(dep) : tables.get(dep).output);
            }
            List<Row> produced = t.transform.apply(input);

            // Enforce expectations with their declared actions, track pass/fail metrics.
            int[] counts = new int[2];
            for (Row r : produced) {
                boolean keep = true;
                for (Expectation e : t.expectations) keep = keep && e.evaluate(r, counts);
                if (keep) t.output.add(r);
            }
            log.info(() -> "Table '" + t.name + "' produced " + t.output.size() + " rows; quality pass="
                    + counts[0] + " fail=" + counts[1]);
        }
        log.info("DLT pipeline complete — dependencies, execution, and quality all managed by the framework");
    }
}
