package com.bank.dlt;

import java.util.List;
import java.util.logging.Logger;

public class DltDemo {
    private static final Logger log = Logger.getLogger(DltDemo.class.getName());

    public static void main(String[] args) {
        DltPipeline pipeline = new DltPipeline();

        // Raw source landing (e.g., from Auto Loader).
        pipeline.addSource("landing", List.of(
            new Row("TRD-1", "SAV2001", 50000),
            new Row("TRD-2", "CUR3001", -5000),   // bad: negative amount
            new Row("TRD-3", "SAV2001", 80000),
            new Row("TRD-4", "", 20000)));          // bad: blank account

        // Declare tables OUT OF ORDER on purpose — DLT figures out the order.
        pipeline.table(new DltTable("gold_fraud", List.of("silver_clean"),
                rows -> rows.stream().filter(r -> r.amount >= 75000).toList()))
                .expect(new Expectation("high_value_only", r -> r.amount >= 75000, Expectation.Action.KEEP));

        pipeline.table(new DltTable("bronze_raw", List.of("landing"), rows -> rows))
                .expect(new Expectation("has_trade_id", r -> !r.tradeId.isBlank(), Expectation.Action.KEEP));

        pipeline.table(new DltTable("silver_clean", List.of("bronze_raw"), rows -> rows))
                .expect(new Expectation("positive_amount", r -> r.amount > 0, Expectation.Action.DROP))
                .expect(new Expectation("valid_account", r -> !r.accountId.isBlank(), Expectation.Action.DROP));

        pipeline.run();
        log.info(() -> "Final gold_fraud rows = " + pipeline.table(new DltTable("gold_fraud", List.of(), r -> r)).output);
    }
}
